ALTER TABLE users ADD COLUMN failed_login_attempts INT NOT NULL DEFAULT 0, ADD COLUMN locked_until DATETIME(6) NULL, ADD COLUMN verified_at DATETIME(6) NULL, ADD COLUMN last_login_at DATETIME(6) NULL;
CREATE TABLE password_reset_tokens (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash VARCHAR(128) NOT NULL, expires_at DATETIME(6) NOT NULL, used_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY uk_password_reset_tokens_hash (token_hash), CONSTRAINT fk_password_reset_tokens_user FOREIGN KEY (user_id) REFERENCES users(id), INDEX idx_password_reset_tokens_user (user_id, expires_at));
CREATE TABLE email_verification_tokens (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash VARCHAR(128) NOT NULL, expires_at DATETIME(6) NOT NULL, used_at DATETIME(6) NULL, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY uk_email_verification_tokens_hash (token_hash), CONSTRAINT fk_email_verification_tokens_user FOREIGN KEY (user_id) REFERENCES users(id), INDEX idx_email_verification_tokens_user (user_id, expires_at));
